    {id:"time", eb:"Your time", title:"How much time do you have?", why:"The plan picks the drills that fit. You can always add the rest.", kind:"single", opts:() => RT_TIME.map(([k, n, h]) => ({k, n, h})), get:() => rt.time, set:k => setV("time", k)}
