function rtPlanText(){ const p = rtP(); return `${p.scope || rtScopeDraft()}\n\nPEOPLE\nBad actors we play:\n${(p.personas || rtPersonaDefaults()).filter(x => x.kind === "bad").map(x => "- " + x.t).join("\n")}\nWell-meaning users who hit an edge:\n${(p.personas || rtPersonaDefaults()).filter(x => x.kind === "good").map(x => "- " + x.t).join("\n")}\nOutside tester: ${p.outside || "[name]"}\n\nTEST SHEET (${rtSheetRows().length} rows; fill outcome, grade, layer, owner)\n${rtSheetRows().map((r, i) => `${i + 1}. ${r.move} → ${r.aim}${r.probe ? " [probe only]" : r.twin ? " [must be answered]" : r.check ? " [control check]" : ""}`).join("\n")}\n\nSTOP RULES AND WELLBEING FLOOR\n${RT_RULES.map(r => "- " + r[0] + ". " + r[1]).join("\n")}\n\nAcknowledged by: ${Object.keys(p.ack).filter(k => p.ack[k]).length} of ${RT_RULES.length} rules ticked. Dated: ${p.dated || "[date]"}.`; }
